    B=attractor(V,1-p,Wopp,owner,{v:[w for w in edges[v] if w in V] for v in V})
    X0,X1=solve(V-B, owner, prio, {v:[w for w in edges[v] if w in V-B] for v in V-B})
    if p==0: return X0, X1|B
    else: return X0|B, X1

