# Berlekamp-Massey over GF(2)
def bm(s):
    n=len(s)
    C=[1]+[0]*n
    B=[1]+[0]*n
    L=0
    m=1
    b=1
    for N in range(n):
        d=s[N]
        for i in range(1,L+1):
