        if d==1:
            T=C[:]
            for i in range(n+1-m):
                C[m+i] ^= B[i]
            if 2*L <= N:
                L = N + 1 - L
                B = T
                m = 1
                b = d
            else:
                m += 1
        else:
            m += 1
    return L,C[:L+1]
